import{_ as e,o as t,c as r,a2 as i}from"./chunks/framework.BqDA2HS7.js";const o="/RefractRouter/automatic-flow.svg",u=JSON.parse('{"title":"自动路由 · Direct 与 DAG","description":"","frontmatter":{},"headers":[],"relativePath":"automatic.md","filePath":"automatic.md"}'),c={name:"automatic.md"};function l(n,a,s,d,h,p){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="自动路由-·-direct-与-dag" tabindex="-1">自动路由 · Direct 与 DAG <a class="header-anchor" href="#自动路由-·-direct-与-dag" aria-label="Permalink to &quot;自动路由 · Direct 与 DAG&quot;">​</a></h1><p><span class="doc-badge research">独立研究入口</span></p><p>自动路由先判断任务结构，再比较整任务 Direct 与 DAG 候选。DAG 的节点可以使用不同模型 与推理等级；合法的独立分支可以并行调用模型。</p><figure class="doc-diagram"><img src="'+o+'" alt="任务经过判断与准入后进入 Direct 或 DAG，再依据风险检查最终候选"><figcaption>能拆分、选择 DAG、候选通过审核，是三个不同判断。</figcaption></figure><h2 id="一次运行的过程" tabindex="-1">一次运行的过程 <a class="header-anchor" href="#一次运行的过程" aria-label="Permalink to &quot;一次运行的过程&quot;">​</a></h2><ol><li>冻结模型池、任务要求、数据域、价格、预算和期限。</li><li>规则或可选 Jev 判断独立工作与依赖；微型任务可跳过额外判别。</li><li>有必要时调用规划模型，生成计划并校验职责、依赖与输出合同。</li><li>Python 依据合法性、能力与质量依据、费用和时间预测选择 Direct 或 DAG。</li><li>调用选定模型；DAG 按依赖执行，最终组合候选。</li><li>检查实际工具与候选风险，按<a href="./adaptive-review.html">自适应最终审核</a>决定审核与交付。</li></ol><h2 id="jev-负责什么" tabindex="-1">Jev 负责什么 <a class="header-anchor" href="#jev-负责什么" aria-label="Permalink to &quot;Jev 负责什么&quot;">​</a></h2><p>Jev 适合回答是否存在值得分别处理的独立工作、分支间是否必须串行等有限问题。 它提供拆分信号，不负责生成完整 DAG、执行工具、结算费用或保证 DAG 更便宜。 节点计划仍由生成模型产出，Python 校验并作最终路线决策。</p><h2 id="为什么可能继续选-direct" tabindex="-1">为什么可能继续选 Direct <a class="header-anchor" href="#为什么可能继续选-direct" aria-label="Permalink to &quot;为什么可能继续选 Direct&quot;">​</a></h2><p>可拆分任务也可能有较高的规划、上下文重复、汇总或审核开销。 预算、期限、数据域、节点准入与预测依据不足，都可能使 Direct 更合适。 选择理由应出现在实际记录，不只显示 Jev 的拆分答案。</p><h2 id="模型池与节点分配" tabindex="-1">模型池与节点分配 <a class="header-anchor" href="#模型池与节点分配" aria-label="Permalink to &quot;模型池与节点分配&quot;">​</a></h2><p>多个可用模型不表示每个节点必须使用不同模型。 节点类型、难度、风险、资料域、上下文、参数、质量依据和现金／参考成本共同影响候选。 缺少独立节点观测时显示使用全局先验；不能把排行榜分数当作该节点已经证明等质。</p><p>模型调用并行与工具执行并行分开处理：独立节点可以并行调用，宿主工具保持既有调度与审批。 汇总等待必要上游完成；节点失败按冻结停止或有界切换规则处理。</p><h2 id="在-dsh-中配置" tabindex="-1">在 DSH 中配置 <a class="header-anchor" href="#在-dsh-中配置" aria-label="Permalink to &quot;在 DSH 中配置&quot;">​</a></h2><p>使用独立的 <strong>RefractAgent 自动路由</strong> 卡片：选择执行模型池、数据域与信任策略， 核对规划／拆分／最终审核用途，设置任务预算、期限、调用与输出限制。 零调用诊断通过后，启用真实执行并选择 <strong>自动路由（真实执行）</strong>。</p><p>“省成本／均衡／质量优先”是历史三档入口，不代表新版两种路由的六策略。 旧模型 ID 为历史读取保留；新设置需要按当前模型目录显式初始化或升级。</p><h2 id="已知边界" tabindex="-1">已知边界 <a class="header-anchor" href="#已知边界" aria-label="Permalink to &quot;已知边界&quot;">​</a></h2><p>当前没有充分证据证明 DAG 在同等或可接受质量下普遍更便宜、更快。 规划、汇总、审核、丢弃和失败尝试均计入总体费用；只比较成功节点会低估总开销。 DSH 的接线通过也不是任意 Agent 的 DAG 协议兼容证据。标准模型网关不自动进入 DAG。</p>',18)])])}const m=e(c,[["render",l]]);export{u as __pageData,m as default};
